#include "reference_attribute_destruction.h"
#include <array>
#include <fstream>
#include <iostream>
#include <stdexcept>
struct Attribute{uint16_t flags;uint32_t token;uintptr_t storage;};
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("oracle required");std::ifstream file(argv[1],std::ios::binary);unsigned cases=0;for(unsigned type=0;type<32;++type)for(unsigned pattern=0;pattern<8;++pattern)for(unsigned count=0;count<=4;++count){Attribute a{uint16_t(type|(pattern&1?0x200:0)|(pattern&4?0x1000:0)),123+pattern,(pattern&2)&&type!=1&&type!=15?0:0x1234567887654321ull};std::array<uint32_t,4>handles{0xffffffffu,7,7,9};std::array<uint32_t,32>actual{},expected{};auto event=[&](uint32_t code,uint32_t value){unsigned i=actual[0]++;actual[1+i*2]=code;actual[2+i*2]=value;};destroyRecoveredReferenceAttributeCandidate(&a,[&](Attribute&,auto visit){if(type==1)visit(handles[count%4]);else for(unsigned i=0;i<count;++i)visit(handles[i]);},[&](uint32_t target,Attribute&){event(1,target);},[&](uint32_t token){event(2,token);},[&](uint32_t type,uintptr_t storage){if(a.token!=0xffffffffu||storage!=a.storage)throw std::runtime_error("release order");event(3,type);},[&](Attribute*){event(4,0);});actual[28]=a.token;actual[29]=a.storage!=0;actual[30]=0xabcd0000u|a.flags;if(!file.read(reinterpret_cast<char*>(expected.data()),sizeof(expected))||actual!=expected)throw std::runtime_error("oracle mismatch");++cases;}char extra;if(file.get(extra))throw std::runtime_error("extra oracle");std::cout<<"x64_attribute_destruction_cases="<<cases<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
